Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$InvocationRoot = (Get-Location).ProviderPath
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$OldConsoleEncoding = [Console]::OutputEncoding
$OldOutputEncoding = $OutputEncoding
$OldCurrentDirectory = [Environment]::CurrentDirectory
$OldPythonUtf8 = $env:PYTHONUTF8
$OldPythonIoEncoding = $env:PYTHONIOENCODING
$OldEmail = $env:VUT_TUTOR_ADMIN_EMAIL
$OldPassword = $env:VUT_TUTOR_ADMIN_PASSWORD

function Write-Info { param([string]$Message) Write-Host ('[INFO] {0}' -f $Message) -ForegroundColor Cyan }
function Write-Ok { param([string]$Message) Write-Host ('[OK] {0}' -f $Message) -ForegroundColor Green }
function Write-Warn { param([string]$Message) Write-Host ('[WARN] {0}' -f $Message) -ForegroundColor Yellow }
function Write-Fail { param([string]$Message) Write-Host ('[FAIL] {0}' -f $Message) -ForegroundColor Red }

function Resolve-UserPath {
    param([string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    if ([System.IO.Path]::IsPathRooted($Value)) { return [System.IO.Path]::GetFullPath($Value) }
    return [System.IO.Path]::GetFullPath((Join-Path $InvocationRoot $Value))
}

function Get-Sha256 {
    param([Parameter(Mandatory=$true)][string]$Path)
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

function Expand-GzipPayload {
    param(
        [Parameter(Mandatory=$true)][string]$Payload,
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$ExpectedSha256
    )
    $compressed = [Convert]::FromBase64String(($Payload -replace '\s',''))
    $input = New-Object System.IO.MemoryStream(,$compressed)
    $gzip = New-Object System.IO.Compression.GZipStream($input,[System.IO.Compression.CompressionMode]::Decompress)
    $output = New-Object System.IO.MemoryStream
    try {
        $gzip.CopyTo($output)
        [System.IO.File]::WriteAllBytes($Path,$output.ToArray())
    }
    finally {
        $output.Dispose()
        $gzip.Dispose()
        $input.Dispose()
    }
    $actual = Get-Sha256 -Path $Path
    if ($actual -ne $ExpectedSha256) {
        throw ('SHA-256 rozbaleného payloadu nesouhlasí pro {0}; actual={1}; expected={2}' -f $Path,$actual,$ExpectedSha256)
    }
}

function Resolve-Python {
    param([string]$Requested)
    if (-not [string]::IsNullOrWhiteSpace($Requested)) {
        $full = Resolve-UserPath -Value $Requested
        if (-not (Test-Path -LiteralPath $full -PathType Leaf)) {
            throw ('PythonPath neexistuje: {0}' -f $full)
        }
        return $full
    }
    foreach ($name in @('python.exe','python','python3')) {
        $command = Get-Command $name -ErrorAction SilentlyContinue
        if ($null -ne $command) { return $command.Source }
    }
    throw 'Python nebyl nalezen. Zadejte -PythonPath.'
}

function New-PayloadDirectory {
    $directory = Join-Path ([System.IO.Path]::GetTempPath()) ('vut-ai-tutor-1.26.5-' + [Guid]::NewGuid().ToString('N'))
    [System.IO.Directory]::CreateDirectory($directory) | Out-Null
    Expand-GzipPayload -Payload $ManagerPayload -Path (Join-Path $directory $ManagerName) -ExpectedSha256 $ManagerSha256
    Expand-GzipPayload -Payload $BootstrapPayload -Path (Join-Path $directory $BootstrapName) -ExpectedSha256 $BootstrapSha256
    Expand-GzipPayload -Payload $PipePayload -Path (Join-Path $directory $PipeName) -ExpectedSha256 $PipeSha256
    return $directory
}

function Invoke-ManagerProcess {
    param(
        [Parameter(Mandatory=$true)][string]$Python,
        [Parameter(Mandatory=$true)][string[]]$Arguments,
        [Parameter(Mandatory=$true)][string]$LogPath
    )
    $stdoutPath = $LogPath + '.stdout.tmp'
    $stderrPath = $LogPath + '.stderr.tmp'
    Remove-Item -LiteralPath $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue

    $previousPreference = $ErrorActionPreference
    try {
        # Windows PowerShell 5.1 converts native stderr into ErrorRecord objects.
        # Continue locally so Python can return its real exit code and diagnostics.
        $ErrorActionPreference = 'SilentlyContinue'
        & $Python @Arguments 1> $stdoutPath 2> $stderrPath
        $code = [int]$LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $previousPreference
    }

    $stdout = if (Test-Path -LiteralPath $stdoutPath) { [System.IO.File]::ReadAllText($stdoutPath) } else { '' }
    $stderr = if (Test-Path -LiteralPath $stderrPath) { [System.IO.File]::ReadAllText($stderrPath) } else { '' }
    [System.IO.File]::WriteAllText($LogPath,($stdout + $stderr),$Utf8NoBom)
    if (-not [string]::IsNullOrEmpty($stdout)) { Write-Host $stdout -NoNewline }
    if (-not [string]::IsNullOrEmpty($stderr)) { Write-Host $stderr -NoNewline -ForegroundColor Red }
    Remove-Item -LiteralPath $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue
    return $code
}

$payloadDirectory = $null
$exitCode = 1
$failureMessage = ''
try {
    [Console]::OutputEncoding = $Utf8NoBom
    $OutputEncoding = $Utf8NoBom
    [Environment]::CurrentDirectory = $InvocationRoot
    $env:PYTHONUTF8 = '1'
    $env:PYTHONIOENCODING = 'utf-8'

    $resolvedReport = Resolve-UserPath -Value $ReportPath
    $resolvedManagerLog = Resolve-UserPath -Value $ManagerLogPath
    if ([string]::IsNullOrWhiteSpace($resolvedManagerLog)) {
        if (-not [string]::IsNullOrWhiteSpace($resolvedReport)) {
            $resolvedManagerLog = $resolvedReport + '.manager.log'
        }
        else {
            $resolvedManagerLog = Join-Path $InvocationRoot 'vut-ai-tutor-1.26.5-verify.manager.log'
        }
    }
    $logParent = Split-Path -Parent $resolvedManagerLog
    if (-not [string]::IsNullOrWhiteSpace($logParent)) {
        [System.IO.Directory]::CreateDirectory($logParent) | Out-Null
    }

    $payloadDirectory = New-PayloadDirectory
    $python = Resolve-Python -Requested $PythonPath
    $manager = Join-Path $payloadDirectory $ManagerName
    $bootstrap = Join-Path $payloadDirectory $BootstrapName
    $pipe = Join-Path $payloadDirectory $PipeName

    Write-Info -Message ('Manager Python: {0}' -f $python)
    Write-Info -Message ('VUT AI Tutor {0}; režim={1}; cíl={2}.' -f $ReleaseVersion,$Mode,$Target)
    if (($Target -eq 'Desktop') -and ($Mode -in @('TutorOnly','Verify')) -and (-not $NoAutoStartDesktop)) {
        Write-Info -Message 'Není-li lokální backend dostupný, adaptér automaticky spustí oficiální Open WebUI Desktop a počká na platné /api/version.'
    }
    Write-Info -Message ('Manager log: {0}' -f $resolvedManagerLog)

    $arguments = @($manager,'--bootstrap-path',$bootstrap,'--pipe-path',$pipe)
    if ($SelfTest) {
        $arguments += '--self-test'
    }
    else {
        $arguments += @('--mode',$Mode,'--target',$Target)
        if (-not [string]::IsNullOrWhiteSpace($DesktopInstallRoot)) { $arguments += @('--desktop-install-root',(Resolve-UserPath -Value $DesktopInstallRoot)) }
        if (-not [string]::IsNullOrWhiteSpace($DesktopDataRoot)) { $arguments += @('--desktop-data-root',(Resolve-UserPath -Value $DesktopDataRoot)) }
        if (-not [string]::IsNullOrWhiteSpace($DesktopConfigRoot)) { $arguments += @('--desktop-config-root',(Resolve-UserPath -Value $DesktopConfigRoot)) }
        if (-not [string]::IsNullOrWhiteSpace($DesktopExecutable)) { $arguments += @('--desktop-executable',(Resolve-UserPath -Value $DesktopExecutable)) }
        if (-not [string]::IsNullOrWhiteSpace($ServerRuntimeConfig)) { $arguments += @('--server-runtime-config',(Resolve-UserPath -Value $ServerRuntimeConfig)) }
        if (-not [string]::IsNullOrWhiteSpace($BaseUrl)) { $arguments += @('--base-url',$BaseUrl) }
        if ($OnlyBaseUrl) { $arguments += '--only-base-url' }
        if (-not [string]::IsNullOrWhiteSpace($TokenFile)) { $arguments += @('--token-file',(Resolve-UserPath -Value $TokenFile)) }
        if (-not [string]::IsNullOrWhiteSpace($Email)) { $arguments += @('--email',$Email) }
        if (-not [string]::IsNullOrWhiteSpace($resolvedReport)) { $arguments += @('--report-path',$resolvedReport) }
        if ($StopDesktopProcesses) { $arguments += '--stop-desktop-processes' }
        if ($SkipOpenWebUIReinstall) { $arguments += '--skip-openwebui-reinstall' }
        if ($NoStartAfterRecovery) { $arguments += '--no-start-after-recovery' }
        if ($NoAutoStartDesktop) { $arguments += '--no-auto-start-desktop' }
        $arguments += @(
            '--http-timeout',[string]$HttpTimeout,
            '--route-timeout',[string]$RouteTimeout,
            '--startup-timeout',[string]$StartupTimeout,
            '--package-timeout',[string]$PackageTimeout,
            '--migration-timeout',[string]$MigrationTimeout
        )
    }

    $needsCredential = (-not $SelfTest) -and ($Mode -in @('TutorOnly','Repair','Verify')) -and $PromptForCredential -and [string]::IsNullOrWhiteSpace($TokenFile)
    if ($needsCredential) {
        $credential = Get-Credential -Message 'Administrátor cílové instance Open WebUI'
        if ($null -eq $credential) { throw 'Přihlašovací dialog byl zrušen.' }
        $env:VUT_TUTOR_ADMIN_EMAIL = $credential.UserName
        $env:VUT_TUTOR_ADMIN_PASSWORD = $credential.GetNetworkCredential().Password
    }

    $exitCode = Invoke-ManagerProcess -Python $python -Arguments $arguments -LogPath $resolvedManagerLog
    if ($exitCode -eq 0) {
        Write-Ok -Message ('Operace VUT AI Tutor {0} dokončena.' -f $ReleaseVersion)
    }
    else {
        $failureMessage = ('VUT AI Tutor manager skončil kódem {0}. Úplný výstup: {1}' -f $exitCode,$resolvedManagerLog)
        Write-Fail -Message $failureMessage
        $KeepPayloadDirectory = $true
    }
}
catch {
    $exitCode = 1
    $failureMessage = $_.Exception.Message
    Write-Fail -Message $failureMessage
    $KeepPayloadDirectory = $true
}
finally {
    $env:VUT_TUTOR_ADMIN_EMAIL = $OldEmail
    $env:VUT_TUTOR_ADMIN_PASSWORD = $OldPassword
    $env:PYTHONUTF8 = $OldPythonUtf8
    $env:PYTHONIOENCODING = $OldPythonIoEncoding
    [Environment]::CurrentDirectory = $OldCurrentDirectory
    [Console]::OutputEncoding = $OldConsoleEncoding
    $OutputEncoding = $OldOutputEncoding

    if (($null -ne $payloadDirectory) -and (-not $KeepPayloadDirectory)) {
        Remove-Item -LiteralPath $payloadDirectory -Recurse -Force -ErrorAction SilentlyContinue
    }
    elseif ($null -ne $payloadDirectory) {
        Write-Info -Message ('Rozbalené zdroje byly ponechány v: {0}' -f $payloadDirectory)
    }
}

if ($exitCode -ne 0) {
    exit $exitCode
}
